from datetime import date

baseline = {"kernel.kptr_restrict": "2", "kernel.yama.ptrace_scope": "1",
            "kernel.unprivileged_bpf_disabled": "1", "net.ipv4.ip_forward": "0"}
# every waiver names a host, a setting, an owner and an end date
waivers = [("k8s-node-07", "net.ipv4.ip_forward", "platform", date(2027, 3, 1)),
           ("build-02", "kernel.yama.ptrace_scope", "ci", date(2026, 10, 1))]
# values collected from each host (only the ones that differ are listed)
fleet = {"web-01": {},
         "k8s-node-07": {"net.ipv4.ip_forward": "1"},
         "build-02": {"kernel.yama.ptrace_scope": "0"},
         "db-03": {"kernel.kptr_restrict": "0",
                   "kernel.unprivileged_bpf_disabled": "2"}}

def waived(host, key, today):
    return any(h == host and k == key and today <= until
               for h, k, owner, until in waivers)

def check(today):
    for host, diff in fleet.items():
        for key, want in baseline.items():
            got = diff.get(key, want)
            if got != want:
                state = "WAIVED" if waived(host, key, today) else "FAIL"
                print(f"{host:12} {key:33} want {want} got {got} {state}")

check(date(2026, 11, 22))

enum lockdown_reason {          /* include/linux/security.h */
    LOCKDOWN_NONE,                  /*  0 */
    LOCKDOWN_MODULE_SIGNATURE,      /*  1 */
    LOCKDOWN_DEV_MEM,               /*  2 */
    /* ... reasons 3 to 16 ... */
    LOCKDOWN_BPF_WRITE_USER,        /* 17 */
    /* ... */
    LOCKDOWN_INTEGRITY_MAX,         /* 21 */
    LOCKDOWN_KCORE,                 /* 22 */
    LOCKDOWN_KPROBES,               /* 23 */
    LOCKDOWN_BPF_READ_KERNEL,       /* 24 */
    /* ... */
    LOCKDOWN_CONFIDENTIALITY_MAX,   /* 30 */
};

/* security/lockdown/lockdown.c, simplified */
static int lock_kernel_down(const char *where, enum lockdown_reason level)
{
    if (kernel_locked_down >= level)
        return -EPERM;              /* can only go up, never down */
    kernel_locked_down = level;
    return 0;
}

static int lockdown_is_locked_down(enum lockdown_reason what)
{
    if (kernel_locked_down >= what) {
        pr_notice("Lockdown: %s: %s is restricted; see man kernel_lockdown.7",
                  current->comm, lockdown_reasons[what]);
        return -EPERM;
    }
    return 0;
}

